7	/**
8	 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
9	 * an existing one — sharing the same last name and postcode but a different telephone (see
10	 * {@link PossibleDuplicate}). Such an owner is still created; the matching owner's id is
11	 * stored in {@code possibleDuplicateOf} so a later read can flag it.
12	 *
13	 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected hard duplicates, so any
14	 * match found here is genuinely a softer one. When several existing owners match, the
15	 * earliest-created (lowest id) is recorded; no match leaves the field unset.
16	 */
17	public class FlagPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        Integer matchId = null;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (PossibleDuplicate.matches(existing, owner)) {
23	                Integer id = existing.getId();
24	                if (id != null && (matchId == null || id < matchId)) {
25	                    matchId = id;
26	                }
27	            }
28	        }
29	        owner.setPossibleDuplicateOf(matchId);
30	    }
31	}
