1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The single definition of an owner's customer code: {@code <REGION>-<HASH8>}, where REGION
9	 * is the region derived from the owner's postcode (see {@link Locality}) and HASH8 is the
10	 * first 8 upper-case hex characters of SHA-256 over the owner's normalized telephone
11	 * followed by its last name. The code carries no sequence number and so is stable for a
12	 * given identity.
13	 *
14	 * <p>Formatting only; the region and identity fields are supplied by the caller
15	 * ({@link AssignOwnerCustomerCode} derives the region and reads the stored fields).
16	 */
17	public final class CustomerCode {
18	
19	    private static final int HASH_LENGTH = 8;
20	
21	    private CustomerCode() {
22	    }
23	
24	    /**
25	     * Format {@code region} and the identity fields into a customer code, e.g.
26	     * {@code format("NSW", "+61412345678", "Smithers")} yields {@code "NSW-1A2B3C4D"} (the
27	     * hash segment being the first 8 upper-case hex digits of SHA-256 over
28	     * {@code telephone + lastName}).
29	     */
30	    public static String format(String region, String telephone, String lastName) {
31	        return region + "-" + hash8(telephone, lastName);
32	    }
33	
34	    /** The region segment of {@code customerCode} (the text before the first {@code '-'}), or
35	     *  {@code null} when the code is absent. */
36	    public static String region(String customerCode) {
37	        if (customerCode == null) {
38	            return null;
39	        }
40	        int dash = customerCode.indexOf('-');
41	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
42	    }
43	
44	    /** The first 8 upper-case hex characters of SHA-256 over {@code telephone + lastName}. */
45	    private static String hash8(String telephone, String lastName) {
46	        byte[] digest = sha256(telephone + lastName);
47	        StringBuilder hex = new StringBuilder(HASH_LENGTH);
48	        for (int i = 0; hex.length() < HASH_LENGTH; i++) {
49	            hex.append(String.format("%02X", digest[i]));
50	        }
51	        return hex.substring(0, HASH_LENGTH);
52	    }
53	
54	    private static byte[] sha256(String value) {
55	        try {
56	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
57	        }
58	        catch (NoSuchAlgorithmException e) {
